import sys

def extract_leaves(value, with_paths=False):
    """Extract scalar leaves from nested dict/list/scalar structures.

    Returns scalars in depth-first order (dict insertion order, list index order).
    With with_paths=True, returns (JSON_pointer, scalar) tuples.

    Raises TypeError for unsupported objects or non-string dict keys.
    Raises ValueError for cycles on the current ancestor path.
    """
    # Stack of (container, iterator, key_for_pointer, parent_pointer)
    # Using an explicit stack avoids recursion so deep nesting (2500+) works
    # without changing sys.setrecursionlimit.

    # Sentinel marking the root when value itself is a scalar.
    ROOT = object()

    if with_paths:
        def visit_scalar(scalar, pointer):
            return (pointer, scalar)
    else:
        def visit_scalar(scalar, pointer):
            return scalar

    # Each stack frame: (container, iterator, pointer_prefix, key_repr)
    # key_repr is the JSON-pointer token for this container ('' for root).
    stack = []
    results = []

    # Determine how to iterate a container.
    def make_iter(container):
        if isinstance(container, dict):
            return iter(container.items())
        elif isinstance(container, (list, tuple)):
            return enumerate(container)
        else:
            return None

    # Validate the root value type up front for scalars.
    def check_scalar(v):
        if v is None or isinstance(v, (str, int, float, bool)):
            return
        raise TypeError(
            "Unsupported object of type %s encountered" % type(v).__name__)

    def check_key(k):
        if not isinstance(k, str):
            raise TypeError("Dict keys must be strings")
        return k

    def escape_key(k):
        # JSON pointer escaping: '~' -> '~0', '/' -> '~1'
        return k.replace('~', '~0').replace('/', '~1')

    def index_token(i):
        return str(i)

    # Main iterative traversal.
    # Frames: [container, iterator, pointer_prefix]
    # pointer_prefix is the pointer of the container itself ('' at root).

    # First, handle root scalar case.
    it = make_iter(value)
    if it is None:
        check_scalar(value)
        return visit_scalar(value, "")

    stack.append([value, it, ""])
    # Track ancestor containers for cycle detection on current path.
    # Each entry corresponds to a stack frame; identity-based.
    ancestors = [id(value)]

    while stack:
        frame = stack[-1]
        container, iterator, prefix = frame
        advanced = False
        for key, child in iterator:
            if isinstance(container, dict):
                check_key(key)
                token = escape_key(key)
            else:
                token = index_token(key)

            child_ptr = prefix + "/" + token if prefix != "" or True else token
            # For root container, prefix is "" and child pointer is "/" + token.
            # For nested containers, prefix is non-empty and same formula works.
            # Root scalar handled separately above.

            child_it = make_iter(child)
            if child_it is not None:
                cid = id(child)
                if cid in ancestors:
                    raise ValueError(
                        "Cycle detected on current ancestor path")
                # Descend: push new frame.
                stack.append([child, child_it, child_ptr])
                ancestors.append(cid)
                advanced = True
                break
            else:
                check_scalar(child)
                results.append(visit_scalar(child, child_ptr))
                advanced = True
                # continue consuming this iterator in next loop turn
                break

        if not advanced:
            # Iterator exhausted; pop frame.
            stack.pop()
            ancestors.pop()

    return results
